from typing import Protocol, runtime_checkable

@runtime_checkable
class Quacker(Protocol):
    def quack(self) -> str:
        ...

class Duck:
    def quack(self) -> str:
        return "Cuac"

class Person:
    def quack(self) -> str:
        return "Finjo ser un pato"

class Robot:
    def beep(self) -> str:
        return "Beep"

def hacer_sonido(entidad: Quacker) -> str:
    return entidad.quack()

print(hacer_sonido(Duck()))
print(hacer_sonido(Person()))
print(isinstance(Duck(), Quacker))
print(isinstance(Robot(), Quacker))
